    testGetExtension(t, mime, [
      // Upper/lower case
      { input: 'text/html', expected: 'html' },
      { input: ' text/html', expected: 'html' },
      { input: 'text/html ', expected: 'html' },

      { input: 'application/x-bogus', expected: null },
      { input: 'bogus', expected: null },
      { input: null, expected: null },
      { input: undefined, expected: null },
      { input: 42, expected: null },
      { input: {}, expected: null },
    ]);
  });
});

it('getAllExtensions()', () => {
